(7687683, 1259208, 42733, '<td valign="top">My pick for yellow in this challenge.</td>', 'My pick for yellow in this challenge.', '2021-02-21 18:50:43.000000', NULL, 1),
(7687688, 1259218, 66597, '<td valign="top">Although this is a lovely photo of a chess set, I dont really see the painting with light aspect; it appears to me that he board is lit underneath.</td>', 'Although this is a lovely photo of a chess set, I dont really see the painting with light aspect; it appears to me that he board is lit underneath.', '2021-02-21 20:44:10.000000', NULL, 1),
(7687689, 1259109, 66597, '<td valign="top">I have to admit this is a pretty nice photo for a rubber ducky. I appreciate the innovative take to painting with light; you might get some DNMC, but I think it works well.</td>', 'I have to admit this is a pretty nice photo for a rubber ducky. I appreciate the innovative take to painting with light; you might get some DNMC, but I think it works well.', '2021-02-21 20:45:11.000000', NULL, 1),
(7687690, 1259208, 66597, '<td valign="top">This is a really lovely photo, and shows your skill in lighting photos well (although the bases the pears are resting on look just a touch hot on the sides). However, Im mixed, as I dont really see a painting with light aspect.</td>', 'This is a really lovely photo, and shows your skill in lighting photos well (although the bases the pears are resting on look just a touch hot on the sides). However, Im mixed, as I dont really see a painting with light aspect.', '2021-02-21 20:46:32.000000', NULL, 1),
(7687691, 1259195, 66597, '<td valign="top">LOL, well, truth in advertising, I guess. The composition isnt terrible, and you did manage to kind of spell out bad. So, kudos for effort at any rate.</td>', 'LOL, well, truth in advertising, I guess. The composition isnt terrible, and you did manage to kind of spell out bad. So, kudos for effort at any rate.', '2021-02-21 20:48:18.000000', NULL, 1),
(7687692, 1259090, 66597, '<td valign="top">This is amazing. Its absolutely a 10 from me.  I wish I had any idea how you did this, and look forward to reading the comments. My pick for the winner.</td>', 'This is amazing. Its absolutely a 10 from me.  I wish I had any idea how you did this, and look forward to reading the comments. My pick for the winner.', '2021-02-21 20:49:34.000000', NULL, 1),
(7687693, 1259137, 66597, '<td valign="top">This is pretty cool - it looks like a lot of work to pull off. As a photo, Im not sure its a knockout, but in terms of the technique, I give it kudos.</td>', 'This is pretty cool - it looks like a lot of work to pull off. As a photo, Im not sure its a knockout, but in terms of the technique, I give it kudos.', '2021-02-21 20:50:25.000000', NULL, 1),
(7687694, 1259072, 66597, '<td valign="top">I really like the object, but find the tree a bit distracting because I either am wishing it were gone or more prominent. Still a great effort and one I hope does well.</td>', 'I really like the object, but find the tree a bit distracting because I either am wishing it were gone or more prominent. Still a great effort and one I hope does well.', '2021-02-21 20:51:22.000000', NULL, 1),
(7687695, 1259219, 66597, '<td valign="top">Nice lighting, but Im not seeing paining with light per se here.</td>', 'Nice lighting, but Im not seeing paining with light per se here.', '2021-02-21 20:51:56.000000', NULL, 1),
(7687696, 1259210, 66597, '<td valign="top">This is outstanding, and one of my picks for a ribbon. It tells a little story and has lovely colors. Well done!</td>', 'This is outstanding, and one of my picks for a ribbon. It tells a little story and has lovely colors. Well done!', '2021-02-21 20:52:35.000000', NULL, 1),
(7687697, 1259153, 66597, '<td valign="top">Lovely scene, but Im vacillating a bit on if it meets the challenge. Ill say it does, as there is no way that palapa was lighted with fill flash. Ill look forward to reading how you did it.</td>', 'Lovely scene, but Im vacillating a bit on if it meets the challenge. Ill say it does, as there is no way that palapa was lighted with fill flash. Ill look forward to reading how you did it.', '2021-02-21 20:53:45.000000', NULL, 1),
(7687698, 1259128, 66597, '<td valign="top">This is a really lovely, evocative scene, but am vacillating on the degree to which you painted with light. That being said, the lighting is great, so will give a good score.</td>', 'This is a really lovely, evocative scene, but am vacillating on the degree to which you painted with light. That being said, the lighting is great, so will give a good score.', '2021-02-21 20:55:33.000000', NULL, 1),
(7687699, 1258870, 66597, '<td valign="top">Very cool. Has a sci-fi type feel - hope this one does well!</td>', 'Very cool. Has a sci-fi type feel - hope this one does well!', '2021-02-21 20:56:04.000000', NULL, 1),
(7687700, 1258932, 66597, '<td valign="top">This is one of those sleeper photos that took me a moment to appreciate- but I do. It has a lovely, ethereal feel, and tells a great story. Well done!</td>', 'This is one of those sleeper photos that took me a moment to appreciate- but I do. It has a lovely, ethereal feel, and tells a great story. Well done!', '2021-02-21 20:56:53.000000', NULL, 1),
