(7687702, 1259214, 66597, '<td valign="top">Very cool! Great use of pure black and pure white, and completely meets the challenge.</td>', 'Very cool! Great use of pure black and pure white, and completely meets the challenge.', '2021-02-21 20:57:41.000000', NULL, 1),
(7687970, 1259219, 100773, '<td valign="top">I like this. Only thing I would change is that the yellow in the background is so mush brighter than your motive, and that draws the attention away.</td>', 'I like this. Only thing I would change is that the yellow in the background is so mush brighter than your motive, and that draws the attention away.', '2021-02-24 17:06:25.000000', NULL, 1),
